      const wf = cutDone ? U * 0.35 * s.noise(tn * 1.3, i * 0.21, 17) * Math.min(1, (tn - o.tc) * 2) : 0;
      q[0] = p[0]; q[1] = p[1];
      p[0] += vx + wf * dt * dt; p[1] += vy + g * dt * dt;
    }
    for (let it = 0; it < 10; it++) {
      for (let i = 0; i < N - 1; i++) {
