        const a = P[i], b = P[i + 1], wa = iw[i], wb = iw[i + 1], ws = wa + wb; if (!ws) continue;
        const dx = b[0] - a[0], dy = b[1] - a[1], dl = Math.hypot(dx, dy) || 1e-6, k = (dl - L) / dl / ws;
