// Kéo vàng: lưỡi mở góc a (rad), mũi hướng theo dir; đặt sao cho điểm cắt nằm giữa hai lưỡi.
const scissors = (c, x, y, dir, a, L, al) => {
  if (al <= 0.01) return;
